16	import https from 'node:https';
17	
18	const POST_TIMEOUT_MS = 2000;
19	
20	// isConfigured(cfg) — cfg is the parsed cave/local.json object (or undefined).
21	// True only when cfg.discord.webhookUrl is a non-empty string that isn't the
22	// example placeholder.
23	export function isConfigured(cfg) {
24	  const url = cfg?.discord?.webhookUrl;
25	  return typeof url === 'string' && url.trim().length > 0 && url !== 'CHANGE_ME';
26	}
27	
28	// postStatus({ botName, color, text, webhookUrl }) — fires a Discord webhook
29	// message with username "[CAVE] <botName>" and the given text as content.
30	// `color` is accepted for a consistent call signature with the rcon
31	// announce() paths but Discord webhooks have no per-message text color, so it
32	// is currently unused here (kept in the signature so callers don't need to
33	// branch). Always resolves; never rejects. Returns false silently on any
34	// failure: bad URL, network error, non-2xx response, or timeout.
35	export function postStatus({ botName, color, text, webhookUrl }) {
36	  return new Promise((resolve) => {
37	    let url;
38	    try {
39	      url = new URL(webhookUrl);
40	    } catch {
41	      return resolve(false);
42	    }
43	
44	    const payload = JSON.stringify({
45	      username: `[CAVE] ${botName}`,
46	      content: String(text),
47	    });
48	
49	    const req = https.request(
50	      {
51	        hostname: url.hostname,
52	        port: url.port || 443,
53	        path: url.pathname + url.search,
54	        method: 'POST',
55	        headers: {
56	          'Content-Type': 'application/json',
57	          'Content-Length': Buffer.byteLength(payload),
58	        },
59	        timeout: POST_TIMEOUT_MS,
60	      },
61	      (res) => {
62	        // Drain the response body so the socket can close cleanly; we don't
63	        // care about the body content, only the status code.
64	        res.on('data', () => {});
65	        res.on('end', () => {
66	          resolve(res.statusCode >= 200 && res.statusCode < 300);
67	        });
68	      }
69	    );
70	
71	    req.on('timeout', () => {
72	      req.destroy();
73	      resolve(false);
74	    });
75	    req.on('error', () => {
76	      resolve(false);
77	    });
78	
79	    req.write(payload);
80	    req.end();
81	  });
82	}
